        if (st->IsOverride()) {
            checker->LogError(diagnostic::OVERRIDE_NOT_PRIVATE, {propVar->Declaration()->Name(), superTypeName},
                              st->Start());
        }
        return;
    }

    if (st->HasAnnotations()) {
