    {
        std::set<Type const *> types {};
        TypeTraverser hcb = [&](Type const *child) {
            if (child != nullptr && types.find(child) == types.end()) {
                types.emplace(child);
                child->Iterate(hcb);
                func(child);
            }
        };

        Iterate(hcb);

        if (types.find(this) == types.end()) {
            func(this);
        }
    }

